package nz.tate.playernotepad;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.awt.geom.Area;
import java.util.function.Consumer;
import javax.swing.SwingUtilities;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.MouseAdapter;

/**
 * Turns a left-button drag on the game canvas into a selection rectangle.
 *
 * <p>Selection is active when it has been armed for one drag (the sidebar button or press key) or
 * while the hold key is down. While active, the press, drag, release and click are consumed so the game
 * never sees them: you don't walk, attack or rotate anything by drawing the box. Escape cancels.
 *
 * <p>Mouse and key events arrive on the AWT thread and the overlay reads the state on the client
 * thread, so the shared fields are volatile.
 */
class AreaSelector extends MouseAdapter implements KeyListener
{
	/** Drags smaller than this in both directions are treated as a cancelled click. */
	static final int MIN_SIZE = 4;

	private final Consumer<Rectangle> onSelect;

	private volatile boolean armed;
	private volatile boolean held;
	private volatile Point start;
	private volatile Point current;
	private volatile boolean swallowClick;

	AreaSelector(Consumer<Rectangle> onSelect)
	{
		this.onSelect = onSelect;
	}

	/** Arms selection for the next drag. */
	void arm()
	{
		armed = true;
	}

	void setHeld(boolean held)
	{
		this.held = held;
	}

	void cancel()
	{
		armed = false;
		start = null;
		current = null;
	}

	/** True when waiting for a drag to begin, so the overlay can show a hint. */
	boolean isWaiting()
	{
		return (armed || held) && start == null;
	}

	/** True when armed for one drag, which Esc can cancel. Holding the key isn't armed: letting go cancels that. */
	boolean isArmed()
	{
		return armed;
	}

	/** The rectangle being dragged, or null when no drag is in progress. */
	Rectangle currentRect()
	{
		Point s = start;
		Point c = current;
		return s == null || c == null ? null : rect(s, c);
	}

	static Rectangle rect(Point a, Point b)
	{
		int x = Math.min(a.x, b.x);
		int y = Math.min(a.y, b.y);
		return new Rectangle(x, y, Math.abs(a.x - b.x), Math.abs(a.y - b.y));
	}

	static boolean bigEnough(Rectangle r)
	{
		return r.width >= MIN_SIZE || r.height >= MIN_SIZE;
	}

	/**
	 * True when any part of {@code shape} overlaps {@code area}, including when one fully contains
	 * the other. Goes through {@link Area} because the client's hulls are SimplePolygons, whose
	 * {@code intersects} only compares ray crossings from the rectangle's corners and so returns
	 * false once the rectangle swallows the shape whole. A flat drag is widened to one pixel, as an
	 * empty rectangle never intersects anything.
	 */
	static boolean touches(Shape shape, Rectangle area)
	{
		return new Area(shape).intersects(area.x, area.y, Math.max(area.width, 1), Math.max(area.height, 1));
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (!(armed || held) || !SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}

		start = e.getPoint();
		current = start;
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (start == null)
		{
			return e;
		}

		current = e.getPoint();
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		Point s = start;
		if (s == null || !SwingUtilities.isLeftMouseButton(e))
		{
			return e;
		}

		Rectangle r = rect(s, e.getPoint());
		armed = false;
		start = null;
		current = null;
		swallowClick = true;
		e.consume();

		if (bigEnough(r))
		{
			onSelect.accept(r);
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (swallowClick)
		{
			swallowClick = false;
			e.consume();
		}
		return e;
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE && (armed || start != null))
		{
			cancel();
			e.consume();
		}
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
	}
}

