package nz.tate.playernotepad;

/** One saved notepad page. Field names are the save format, so don't rename them. */
final class Notepad
{
	String id;
	String title;
	String text;
	/** When the text or title last changed, in epoch milliseconds. */
	long updated;

	Notepad()
	{
	}

	Notepad(String id, String title, String text, long updated)
	{
		this.id = id;
		this.title = title;
		this.text = text;
		this.updated = updated;
	}
}

